text:
.banner::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--limit-stripe);
}
.pip {
  transform-origin: bottom;
}
.on {
  animation: fill 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  animation-delay: var(--pip-delay);
}
@keyframes fill {
  from {
    transform: scaleY(0.15);
    opacity: 0.4;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}
.ghost svg {
  transition: transform 0.25s ease;
}
.rotated {
  transform: rotate(180deg);
}
.banner :is(a, button):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.more {
  transition: grid-template-rows 0.25s ease;
}
@media (prefers-reduced-motion: reduce) {
  .on {
    animation: none;
  }
  .more,
  .ghost svg {
    transition: none;
  }
}
